--
-- Name: episode_renders; Type: TABLE; Schema: toonflow; Owner: rust_toon
--

CREATE TABLE toonflow.episode_renders (
    id bigint NOT NULL,
    project_id bigint NOT NULL,
    script_id bigint NOT NULL,
    version integer NOT NULL,
    object_path text NOT NULL,
    file_path text NOT NULL,
    cover_path text,
    status text DEFAULT 'ready'::text NOT NULL,
    source_video_ids bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_current boolean DEFAULT false NOT NULL,
    created_by uuid NOT NULL,
    export_task_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT episode_renders_current_is_ready CHECK (((NOT is_current) OR (status = 'ready'::text))),
    CONSTRAINT episode_renders_file_path_not_blank CHECK ((btrim(file_path) <> ''::text)),
